(val, ctx) => {
            const result = check(val);
            const setError = () => ctx.addIssue({
                code: ZodIssueCode.custom,
                ...getIssueProperties(val),
            });
            if (typeof Promise !== "undefined" && result instanceof Promise) {
                return result.then((data) => {
                    if (!data) {
                        setError();
                        return false;
                    }
                    else {
                        return true;
                    }
                });
            }
            if (!result) {
                setError();
                return false;
            }
            else {
                return true;
            }
        }

(event, context) => {
    if (event.retention === "persistent" && event.sequence === null) {
        context.addIssue({ code: z.ZodIssueCode.custom, path: ["sequence"], message: "persistent events require a sequence" });
    }
    if (event.retention === "ephemeral" && event.sequence !== null) {
        context.addIssue({ code: z.ZodIssueCode.custom, path: ["sequence"], message: "ephemeral events cannot have a sequence" });
    }
}

(record, context) => {
    if ((record.createdBy === "agent") !== (record.createdByAgentId !== null))
        context.addIssue({ code: z.ZodIssueCode.custom, path: ["createdByAgentId"], message: "createdByAgentId must be present exactly for agent-created evidence" });
    if (record.quality.status === "unreviewed" && record.quality.reviewId !== null)
        context.addIssue({ code: z.ZodIssueCode.custom, path: ["quality", "reviewId"], message: "unreviewed Evidence must not name a Review" });
    if (record.quality.status !== "unreviewed" && record.quality.reviewId === null)
        context.addIssue({ code: z.ZodIssueCode.custom, path: ["quality", "reviewId"], message: "reviewed or rejected Evidence must name a Review" });
}

