(value, context) => {
    if (value.operation === "THREAD_AWAIT") {
        const threadIds = value.threadIds ?? [];
        if (new Set(threadIds).size !== threadIds.length)
            context.addIssue({ code: "custom", path: ["threadIds"], message: "threadIds must be unique" });
        if (value.policy === "minimum_count" && (value.minimumCount === null || value.minimumCount === undefined || value.minimumCount > threadIds.length))
            context.addIssue({ code: "custom", path: ["minimumCount"], message: "minimum_count requires a value no greater than threadIds.length" });
        if (value.policy === "deadline" && value.deadline === null)
            context.addIssue({ code: "custom", path: ["deadline"], message: "deadline policy requires deadline" });
    }
    if (value.operation === "STOP" && value.threadId === null && value.programId === null)
        context.addIssue({ code: "custom", path: ["threadId"], message: "STOP requires threadId or programId" });
}

