(value, context) => {
    if (value.producerAgentIds.includes(value.reviewerAgentId))
        context.addIssue({ code: "custom", path: ["reviewerAgentId"], message: "reviewer must be independent from every producer" });
}

(value, context) => {
    if ((value.verdict === "REVISE" || value.verdict === "REDESIGN") && !value.defects.length && value.criteria.every((criterion) => criterion.status === "PASS" || criterion.status === "NOT_APPLICABLE"))
        context.addIssue({ code: "custom", path: ["verdict"], message: `${value.verdict} needs a failing or inconclusive criterion or a recorded defect; when every criterion passes and no defect is open, the verdict is PASS` });
    if (value.verdict !== "PASS")
        return;
    if (value.independenceCheck !== "pass")
        context.addIssue({ code: "custom", path: ["verdict"], message: "PASS requires an independent reviewer" });
    if (value.missingRequiredInputs.length)
        context.addIssue({ code: "custom", path: ["missingRequiredInputs"], message: "PASS cannot omit required inputs" });
    if (value.criteria.some((criterion) => criterion.required !== false && (criterion.status === "FAIL" || criterion.status === "INCONCLUSIVE")))
        context.addIssue({ code: "custom", path: ["criteria"], message: "PASS requires every required criterion to pass" });
    if (value.defects.some((defect) => defect.blocking || defect.severity === "blocking" || defect.severity === "major"))
        context.addIssue({ code: "custom", path: ["defects"], message: "PASS cannot contain an open blocking or major defect" });
}

(value, context) => {
    if (value.operation === "THREAD_AWAIT") {
        const threadIds = value.threadIds ?? [];
        if (new Set(threadIds).size !== threadIds.length)
            context.addIssue({ code: "custom", path: ["threadIds"], message: "threadIds must be unique" });
        if (value.policy === "minimum_count" && (value.minimumCount === null || value.minimumCount === undefined || value.minimumCount > threadIds.length))
            context.addIssue({ code: "custom", path: ["minimumCount"], message: "minimum_count requires a value no greater than threadIds.length" });
        if (value.policy === "deadline" && value.deadline === null)
            context.addIssue({ code: "custom", path: ["deadline"], message: "deadline policy requires deadline" });
    }
    if (value.operation === "STOP" && value.threadId === null && value.programId === null)
        context.addIssue({ code: "custom", path: ["threadId"], message: "STOP requires threadId or programId" });
}

